{"label": "56c3f96b6f148760c9f5", "speaker_changes_inside": "no", "view": "own_sincere", "referents": [{"word": "we", "refers_to": "the Bitcoin community / the speaker and his fellow Bitcoiners", "inside": false, "changes_assertion": "no"}, {"word": "us", "refers_to": "the Bitcoin community / the speaker and his fellow Bitcoiners", "inside": false, "changes_assertion": "no"}, {"word": "it", "refers_to": "Bitcoin", "inside": true, "changes_assertion": "no"}], "conditions": [{"text": "Until we get better as humans and more people look to us for advice on life", "inside": true}], "retraction": "none", "time_ok": "yes", "proposition": "Until Bitcoiners improve themselves as humans and become people others look to for life advice, Bitcoin will remain a niche thing whose holders push people away.", "certainty": "likely", "speaker_is": "host", "speaker_evidence": "Guys, look, I'm not the I'm not like a uh a a looks maxer by any means"},
